@pytest.mark.parametrize("scenario_case", _PARAM_CASES, ids=_PARAM_IDS)
def test_add_pet(api_client, scenario_case, config_test_data):
    """
    Test adding a new pet to the store.
    
    This covers various scenarios based on the test data provided in pet.json.
    """
    endpoint = '/pet'
    headers = {'Content-Type': 'application/json'}
    payload = {key: scenario_case[key] for key in scenario_case if key in ["name", "photoUrls", "id", "category", "tags", "status"]}
    
    # Merge with default test data but do not override required fields if provided by scenario
    payload = {**config_test_data, **payload}
    
    # Validate request payload
    request_validation = schema_validator.validate_json(payload, "Pet")
    assert request_validation['valid'], f"Request payload validation failed: {request_validation.get('message')}"

    # Make API request
    response = api_client.post(endpoint, data=json.dumps(payload), headers=headers)
    
    # Validate response status code
    expected_status_code = scenario_case.get('statusCode', 200)
    assert response.status_code == expected_status_code, f"Expected {expected_status_code}, got {response.status_code}"

    # Validate response schema
    response_validation = schema_validator.validate_schema_by_response(endpoint, 'post', str(response.status_code), response)
    assert response_validation['valid'], f"Response validation failed: {response_validation.get('message')}"

@pytest.mark.parametrize("auth_scenario", ["valid", "invalid", "missing"], ids=["Valid Auth", "Invalid Auth", "Missing Auth"])
def test_authentication(api_client, auth_scenario):
    """
    Test authentication scenarios for adding a pet.
    
    - Valid authentication
    - Invalid authentication
    - Missing authentication
    """
    endpoint = '/pet'
    headers = {'Content-Type': 'application/json'}
    payload = {
        "name": "doggie",
        "photoUrls": ["http://example.com/photo1"]
    }

    if auth_scenario == "invalid":
        headers['Authorization'] = "Bearer invalid_token"
    elif auth_scenario == "missing":
        headers.pop('Authorization', None)
    
    # Make API request
    response = api_client.post(endpoint, data=json.dumps(payload), headers=headers)
    
    # Validate response for authentication scenarios
    if auth_scenario == "valid":
        assert response.status_code == 200, f"Expected 200, got {response.status_code}"
    else:
        assert response.status_code in [401, 403], f"Expected 401 or 403 for {auth_scenario}, got {response.status_code}"
